(31211, 'Hebrews 3:15', 'Hebrews', 3, 15, 'لکه څنګه چې د خدای په کلام کې ویل شوي دي: «که چېرې نن تاسو اواز واورئ د خدای نو مه سختوئ خپل زړونه لکه څنګه چې ستاسو پلرونو د سرکښۍ په وخت کې وکړل»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_15.mp3', '', 1761754199, 1761754199),
(31212, 'Hebrews 3:16', 'Hebrews', 3, 16, 'نو بیا هغوی څوک وو چې سره له دې چې د خدای اواز یې واورېد، خو بیا یې هم د هغه په وړاندې سرکښي وکړه؟ ایا دا هماغه خلک نه وو چې موسی د مصر څخه راوویستل؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_16.mp3', '', 1761754199, 1761754199),
(31213, 'Hebrews 3:17', 'Hebrews', 3, 17, 'او خدای د چا نه تر څلوېښتو کالو پورې خفه ؤ؟ ایا دا هغه خلک نه وو چې ګناه یې وکړه او مړي یې په دښته کې پراته وو؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_17.mp3', '', 1761754199, 1761754199),
(31214, 'Hebrews 3:18', 'Hebrews', 3, 18, 'او چاته یې قسم وخوړ چې هغوی به هېڅکله هم هغې ارامۍ ته وردننه نه شي؟ ایا دا هغه خلک نه وو چې د خدای د امر څخه یې سرغړونه وکړه؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_18.mp3', '', 1761754199, 1761754199),
(31215, 'Hebrews 3:19', 'Hebrews', 3, 19, 'نو مونږ وینو چې هغوی ونه شو کولای هغې ارامۍ ته وردننه شي، ځکه چې هغوی ایمان نه درلود.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews3_verse_19.mp3', '', 1761754199, 1761754199),
(31216, 'Romans 7:1', 'Romans', 7, 1, 'ای خویندو او ورونو! تاسو چې د شریعت څخه خبر یئ، ایا تاسو نه پوهېږئ چې شریعت په هغو ټولو کسانو باندې عملي کیږي چې ترڅو پورې هغوی ژوندي وي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_1.mp3', '', 1761754199, 1761754199),
(31217, 'Romans 7:2', 'Romans', 7, 2, 'د مثال په ډول د شریعت له مخې یوه ښځه تر هغه وخته پورې د خپل مېړه سره تړاو لري چې مېړه یې ژوندی وي، خو که چېرې مېړه یې مړ شي، نو هغه د واده د قانون د قید نه ازاده ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_2.mp3', '', 1761754199, 1761754199),
(31218, 'Romans 7:3', 'Romans', 7, 3, 'نو له دې امله که چېرې هغه ښځه په داسې حال کې چې مېړه یې ژوندی وي او هغه د بل چا سره اړیکې ولري، نو هغه زناکاره ګڼل کیږي. خو که چېرې د هغې مېړه مړ شي، نو هغه د شریعت له مخې ازاده ده او که چېرې هغه د بل چا سره واده وکړي، نو زناکاره نه ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_3.mp3', '', 1761754199, 1761754199),
(31219, 'Romans 7:4', 'Romans', 7, 4, 'ای خویندو او ورونو! نو په همدې ډول تاسو هم چې د مسیح د بدن غړي یئ، د شریعت په وړاندې مړه شوي یئ او اوس د هغه چا سره تړاو لرئ چې د مړو نه بیا راژوندی شوی دی، ترڅو وکولای شئ چې خدای ته په خدمت کولو کې ګټور تمام شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_4.mp3', '', 1761754199, 1761754199),
(31220, 'Romans 7:5', 'Romans', 7, 5, 'کله چې مونږ د خپل انساني فطرت له مخې ژوند کاوه، نو شریعت مونږ نفساني غوښتنو ته هڅولو او په مونږ کې یې کار کاوه چې نتیجه یې مرګ دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_5.mp3', '', 1761754199, 1761754199),
(31221, 'Romans 7:6', 'Romans', 7, 6, 'اوس مونږ د شریعت نه ازاد شوي یو او د هغه څه په وړاندې چې مونږ یې بندیان ساتلو، مړه شوي یو. نو مونږ نور په هغې زړې طریقې نه چې په شریعت کې لیکل شوي دي، بلکې په نوې طریقې د روح القدس په مرسته د خدای خدمت کوو. شریعت او ګناه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_6.mp3', '', 1761754199, 1761754199),
(31222, 'Romans 7:7', 'Romans', 7, 7, 'نو مونږ بیا څه ووایو؟ ایا په خپله شریعت ګناه ده؟ هېڅکله نه! که چېرې شریعت نه وای، نو ما به ګناه نه وای پېژندلې. که چېرې شریعت نه وای ویلي: «د نورو څخه د کوم شي تمه مه کوه،» نو زه به هېڅکله په دې نه وای پوه شوی چې تمه څه شی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_7.mp3', '', 1761754199, 1761754199),
(31223, 'Romans 7:8', 'Romans', 7, 8, 'خو ګناه د همدې حکم په وسیله دا موقعه تر‌لاسه کړه چې په ما کې هر ډول تمه کول پیدا کړي. ځکه پرته له شریعت نه ګناه مړه ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_8.mp3', '', 1761754199, 1761754199),
(31224, 'Romans 7:9', 'Romans', 7, 9, 'یو وخت زه بې له شریعته ژوندی وم، خو کله چې د شریعت حکم راغی، نو ګناه ژوندۍ شوه او زه مړ شوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_9.mp3', '', 1761754199, 1761754199),
(31225, 'Romans 7:10', 'Romans', 7, 10, 'هماغه حکم چې باید ماته یې ژوند راکړی وای، ماته یې مرګ راوړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_10.mp3', '', 1761754199, 1761754199),
(31226, 'Romans 7:11', 'Romans', 7, 11, 'ځکه د دې حکم په وسیله ګناه ته موقعه په لاس ورغله او زه یې وغولولم او مړ یې کړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_11.mp3', '', 1761754199, 1761754199),
(31227, 'Romans 7:12', 'Romans', 7, 12, 'نو بیا شریعت سپېڅلی دی او حکمونه یې هم سپېڅلي، عادلانه او ښه دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_12.mp3', '', 1761754199, 1761754199),
(31228, 'Romans 7:13', 'Romans', 7, 13, 'خو ایا یو ښه شی زما د مرګ سبب ګرځي؟ هېڅکله نه! بلکې دا ګناه وه چې د هغه ښه شي په وسیله یې زه ووژلم، د دې دپاره چې زه پوه شم چې ګناه څه شی دی. خو د شریعت حکم د ګناه بې‌حده بدي ښکاره کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_13.mp3', '', 1761754199, 1761754199),
(31229, 'Romans 7:14', 'Romans', 7, 14, 'ځکه چې مونږ پوهېږو چې شریعت روحاني دی، خو زه جسماني یم او لکه د یو غلام په شان په ګناه باندې خرڅ شوی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_14.mp3', '', 1761754199, 1761754199),
(31230, 'Romans 7:15', 'Romans', 7, 15, 'زه نه پوهېږم چې څه کوم، ځکه زه چې څه غواړم چې ویې کړم هغه نه کوم، خو هماغه کار کوم چې کرکه ترې لرم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_15.mp3', '', 1761754199, 1761754199),
(31231, 'Romans 7:16', 'Romans', 7, 16, 'اوس چې زه هغه کار کوم چې نه غواړم ویې کړم، نو دا د دې څرګندونه کوي چې زه دا منم چې شریعت ښه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_16.mp3', '', 1761754199, 1761754199),
(31232, 'Romans 7:17', 'Romans', 7, 17, 'نو اوس زه هغه څوک نه یم چې دا کار کوم، بلکې دا ګناه ده چې په ما کې اوسیږي او دا کار کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_17.mp3', '', 1761754199, 1761754199),
(31233, 'Romans 7:18', 'Romans', 7, 18, 'زه پوهېږم چې زما په انساني فطرت کې نېکي نشته، ځکه زه غواړم چې ښه کار وکړم، خو کولای یې نه شم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_18.mp3', '', 1761754199, 1761754199),
(31234, 'Romans 7:19', 'Romans', 7, 19, 'ځکه کوم ښه کار چې زه غواړم ویې کړم، هغه نه کوم، خو کوم بد کار چې زه یې نه غواړم، هغه کوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_19.mp3', '', 1761754199, 1761754199),
(31235, 'Romans 7:20', 'Romans', 7, 20, 'نو اوس چې زه کوم کار چې نه غواړم ویې کړم، هغه کوم، نو زه د هغه کار سرته رسوونکی نه یم، بلکې دا ګناه ده چې په ما کې اوسیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_20.mp3', '', 1761754199, 1761754199),
(31236, 'Romans 7:21', 'Romans', 7, 21, 'نو زه په دې قانون پوه شوم هرکله چې زه وغواړم کوم ښه کار وکړم، نو بدي مې له لاسه وشي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_21.mp3', '', 1761754199, 1761754199),
(31237, 'Romans 7:22', 'Romans', 7, 22, 'ځکه چې زه په باطن کې د خدای په شریعت باندې خوشحاله یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_22.mp3', '', 1761754199, 1761754199),
(31238, 'Romans 7:23', 'Romans', 7, 23, 'خو زه وینم چې په ما کې یو بل قانون کار کوي چې زما د ذهن د قانون سره په جنګ کې دی او ما د هغې ګناه د قانون بندي کوي چې په ما کې کار کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_23.mp3', '', 1761754199, 1761754199),
(31239, 'Romans 7:24', 'Romans', 7, 24, 'زه څومره بدبخته انسان یم. څوک کولای شي چې ما د دې بدن نه چې ما مرګ ته سپاري، خلاص کړي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_24.mp3', '', 1761754199, 1761754199),
(31240, 'Romans 7:25', 'Romans', 7, 25, 'د خدای شکر کوم چې ماته زمونږ د څښتن عیسی مسیح په وسیله خلاصون راکوي. نو بیا زه په خپل ذهن سره د خدای د شریعت غلامي کوم، خو په نفساني توګه زه د ګناه د قانون غلامي کوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans7_verse_25.mp3', '', 1761754199, 1761754199),
(31241, 'Acts 5:1', 'Acts', 5, 1, 'خو یو سړی ؤ چې حنانیا نومېده او ښځه یې سفیره نومېدله. هغوی خپله یوه ټوټه ځمکه خرڅه کړه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts5_verse_1.mp3', '', 1761754199, 1761754199),
(31242, 'Acts 5:2', 'Acts', 5, 2, 'او په داسې حال کې چې ښځه یې هم پوهېدله چې هغه یو څه پیسې یې د ځان سره وساتلې او پاتې پیسې یې رسولانو ته راوړلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts5_verse_2.mp3', '', 1761754199, 1761754199),
(31243, 'Acts 5:3', 'Acts', 5, 3, 'خو پطروس هغه ته وویل: «ای حنانیا، ته ولې شیطان ته تسلیم شوې او دې ته یې مجبور کړې چې روح القدس ته دروغ ووایې او یو څه پیسې چې د ځمکې د خرڅولو څخه دې لاسته راوړې دي، خپل ځان ته وساتې؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts5_verse_3.mp3', '', 1761754199, 1761754199),
(31244, 'Acts 5:4', 'Acts', 5, 4, 'ایا د خرڅولو څخه مخکې هغه ځمکه ستا نه وه؟ کله چې دې خرڅه کړه هغه پیسې ستا نه وې؟ نو بیا دې څنګه فکر وکړ چې داسې کار وکړې؟ تا انسانانو ته نه بلکې خدای ته دې دروغ ویلي دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts5_verse_4.mp3', '', 1761754199, 1761754199),
(31245, 'Acts 5:5', 'Acts', 5, 5, 'کله چې حنانیا دا خبرې واورېدلې، نو هغه راولوېد او مړ شو. نورو ټولو چې دا واورېدل، ډېر ووېرېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts5_verse_5.mp3', '', 1761754199, 1761754199),
(31246, 'Acts 5:6', 'Acts', 5, 6, 'بیا یو څو ځوانان راغلل، د هغه مړی یې په کفن کې تاو کړ، هغه یې یووړ او ښخ یې کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts5_verse_6.mp3', '', 1761754199, 1761754199),
(31247, 'Acts 5:7', 'Acts', 5, 7, 'نژدې درې ساعته وروسته د هغه ښځه سفیره راننوتله او خبره نه وه چې څه شوي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts5_verse_7.mp3', '', 1761754199, 1761754199),
(31248, 'Acts 5:8', 'Acts', 5, 8, 'پطروس د هغې څخه پوښتنه وکړه: «ماته ووایه چې تاسو خپله ځمکه په همدومره پیسو خرڅه کړې وه؟» هغې ځواب ورکړ: «هو، په همدې پیسو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts5_verse_8.mp3', '', 1761754199, 1761754199),
(31249, 'Acts 5:9', 'Acts', 5, 9, 'پطروس هغې ته وویل: «تاسو دواړو څنګه داسې پرېکړه وکړه چې د څښتن روح وازمایئ؟ ګوره، کومو خلکو چې ستا مېړه ښخ کړ، هغوی همدا‌اوس په دروازه کې ولاړ دي او هغوی به تا هم یوسي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts5_verse_9.mp3', '', 1761754199, 1761754199),
(31250, 'Acts 5:10', 'Acts', 5, 10, 'سمدلاسه هغه ښځه د پطروس په پښو کې راولوېدله او مړه شوه. کله چې هغه ځوانان راننوتل، نو ویې لیدل چې هغه هلته مړه پرته ده، نو د هغې مړی یې هم یووړ او د خپل مېړه په خوا کې یې ښخه کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts5_verse_10.mp3', '', 1761754199, 1761754199),
(31251, 'Acts 5:11', 'Acts', 5, 11, 'د کلیسا ټول خلک او نور کسان چې د دې پېښې نه خبر شول، نو ډېر ووېرېدل. د رسولانو معجزې او حیرانوونکي کارونه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts5_verse_11.mp3', '', 1761754199, 1761754199),
(31252, 'Acts 5:12', 'Acts', 5, 12, 'رسولانو د خلکو په منځ کې ډېر حیرانوونکي کارونه وکړل او ډېرې معجزې یې وښودلې. ایمانداران به د سلیمان په برنډه کې یوځای سره راټولېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts5_verse_12.mp3', '', 1761754199, 1761754199),
(31253, 'Acts 5:13', 'Acts', 5, 13, 'که څه هم خلکو هغوی ته په درنه سترګه کتل، خو کوم خلک چې د دوی په ډله کې نه وو، د هغوی څخه هېچا هم زړه نه شو کولای چې د ایماندارانو سره یوځای شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts5_verse_13.mp3', '', 1761754199, 1761754199),
