(31297, 'Galatians 5:15', 'Galatians', 5, 15, 'خو که چېرې تاسو په یو بل باندې خوله لګوئ او یو بل ته زیان رسوئ، نو بیا پام کوئ، که نه، نو یو بل به بالکل له منځه یوسئ. نفساني غوښتنې او د روح القدس ثمره', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians5_verse_15.mp3', '', 1761754199, 1761754199),
(31298, 'Galatians 5:16', 'Galatians', 5, 16, 'نو زه دا وایم، که چېرې تاسو خپل ژوند د روح القدس د لارښوونې سره سم تېر کړئ، نو بیا به د خپلو نفساني غوښتنو له مخې کوم کار نه کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians5_verse_16.mp3', '', 1761754199, 1761754199),
(31299, 'Galatians 5:17', 'Galatians', 5, 17, 'ځکه چې نفساني غوښتنې د روح القدس د غوښتنو په خلاف دي او څه چې روح القدس غواړي هغه د نفساني طبیعت په خلاف دي. له دې امله تاسو نه شئ کولای هرڅه چې مو زړه وغواړي هغه وکړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians5_verse_17.mp3', '', 1761754199, 1761754199),
(31300, 'Galatians 5:18', 'Galatians', 5, 18, 'خو که چېرې تاسو د خدای د روح القدس په لارښوونه روان یئ، نو بیا مجبوره نه یئ چې د شریعت تابع اوسئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians5_verse_18.mp3', '', 1761754199, 1761754199),
(31301, 'Galatians 5:19', 'Galatians', 5, 19, 'د نفساني غوښتنو کارونه ښکاره دي: جنسي بد‌اخلاقي، ناپاکي، عیاشي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians5_verse_19.mp3', '', 1761754199, 1761754199),
(31302, 'Galatians 5:20', 'Galatians', 5, 20, 'بت‌پرستي، جادوګري، دښمني، جګړې، کینه، قهر او غضب، ځان خوښونه، بې‌اتفاقي، ډله بازي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians5_verse_20.mp3', '', 1761754199, 1761754199),
(31303, 'Galatians 5:21', 'Galatians', 5, 21, 'بخیلي، نشه، مستي او داسې نور. زه تاسو ته بیا خبرداری درکوم لکه څنګه چې مخکې مې هم درکړی ؤ، څوک چې داسې کارونه کوي د خدای د پاچاهۍ په میراث کې به برخه ونه لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians5_verse_21.mp3', '', 1761754199, 1761754199),
(31304, 'Galatians 5:22', 'Galatians', 5, 22, 'خو د روح القدس ثمره دا ده: مینه، خوشحالي، ارامي، صبر، مهرباني، نېکي، وفاداري،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians5_verse_22.mp3', '', 1761754199, 1761754199),
(31305, 'Galatians 5:23', 'Galatians', 5, 23, 'نرمي او په خپل نفس باندې واک لرل. هېڅ شریعت د دې کارونو په خلاف نه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians5_verse_23.mp3', '', 1761754199, 1761754199),
(31306, 'Galatians 5:24', 'Galatians', 5, 24, 'نو څوک چې د عیسی مسیح پیروان دي، هغوی خپل انساني طبیعت د خپلو ټولو هوسونو او غوښتنو سره په صلیب کړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians5_verse_24.mp3', '', 1761754199, 1761754199),
(31307, 'Galatians 5:25', 'Galatians', 5, 25, 'که چېرې مونږ د روح القدس په وسیله ژوند کوو، نو باید خپل ژوند د روح القدس د لارښوونې له مخې جوړ کړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians5_verse_25.mp3', '', 1761754199, 1761754199),
(31308, 'Galatians 5:26', 'Galatians', 5, 26, 'نو باید غرور ونه کړو، یو بل ونه ځوروو او د یو بل سره بخیلي ونه کړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians5_verse_26.mp3', '', 1761754199, 1761754199),
(31309, 'Matthew 26:1', 'Matthew', 26, 1, 'کله چې عیسی خپلې خبرې خلاصې کړې، نو خپلو شاګردانو ته یې وویل:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_1.mp3', '', 1761754199, 1761754199),
(31310, 'Matthew 26:2', 'Matthew', 26, 2, '«لکه څنګه چې تاسو خبر یئ چې دوه ورځې وروسته به د فسحې اختر وي او د انسان زوی به دښمنانو ته په لاس ورکړل شي چې په صلیب باندې وځړول شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew26_verse_2.mp3', '', 1761754199, 1761754199);